        q.append(dict(q=f'传统上认为《{e["n"]}》写于哪里？',a=plain(e["place"]),o=[plain(x["place"]) for x in eps]))
        q.append(dict(q=f'「{vtext(e["kv"])[:36]}……」（钥节）出自哪卷？',a=e["n"],o=names))
