def build(eps):
    b=['<h2 id="m1">一、口诀</h2><div class="mnem glass reveal"><p class="big">马太君王讲天国，<br>马可仆人走得急，<br>路加人子寻失丧，<br>约翰神子赐生命。</p><p class="note">四句对应四卷的画像与钥字：君王·天国 / 仆人·立刻 / 人子·救恩 / 神子·生命。</p></div>']
    b.append('<div class="mnem glass reveal"><p class="big">人狮牛鹰四活物，<br>太可路约次第出。</p><p class="note">耶柔米的传统配对（参结1:10；启4:7）：马太=人、马可=狮、路加=牛、约翰=鹰。这是教会传统的记忆法，不是经文本身的规定（爱任纽的配对略有不同）。</p></div>')
    b.append('<div class="chips">'+"".join(f'<a class="chip" href="{e["fn"]}" style="--c:{e["col"]}"><span>{e["ic"]}</span>{e["ab"]}<small>{e["kw"]}</small></a>' for e in eps)+'</div>')
    b.append('<div class="mnem glass reveal"><p class="big">七神迹：酒 · 子 · 池 · 饼 · 海 · 眼 · 拉撒路<br>七我是：粮 · 光 · 门 · 牧 · 复活 · 道路 · 葡萄树</p><p class="note">约翰福音的两组“七”。前者按出现次序（2；4；5；6；6；9；11 章），后者为 6；8；10；10；11；14；15 章。</p></div>')
    b.append('<div class="mnem glass reveal"><p class="big">十架七言：赦 · 救 · 托 · 弃 · 渴 · 成 · 交</p><p class="note">父啊赦免他们 → 今日在乐园 → 看你的儿子/母亲 → 为什么离弃我 → 我渴了 → 成了 → 将灵魂交在你手里。</p></div>')
    b.append('<h2 id="m2">二、四卷钥字 · 钥节 · 记忆钩</h2><div class="tbl"><table><thead><tr><th>书卷</th><th>钥字</th><th>钥节</th><th>记忆钩</th><th>何时 · 何地</th></tr></thead><tbody>'+"".join(f'<tr><td class="bk"><a href="{e["fn"]}">{e["ic"]} {e["n"]}</a></td><td><b class="key">{e["kw"]}</b></td><td><button type="button" class="vs" data-t="{esc(vtext(e["kv"]))}">{e["kv"]}</button></td><td>{esc(plain(e["mn"]))}</td><td><small>{esc(plain(e["date"]))} · {esc(plain(e["place"]))}</small></td></tr>' for e in eps)+'</tbody></table></div>')
    b.append('<h2 id="m3">三、记忆卡（点按翻转）</h2><div class="fc-tools"><button id="fcshuf" class="btn">🔀 打乱</button><button id="fcall" class="btn">🔁 全部翻回</button></div><div class="cards" id="fcards">'+"".join(f'<div class="flip sm" tabindex="0" role="button"><div class="fi-in"><div class="ff"><span>{ic}</span><b>{t}</b><em>{esc(h)}</em></div><div class="fb"><p>{esc(vtext(r))}</p><small>— {r}</small></div></div></div>' for ic,t,h,r in FC)+'</div>')
    b.append('<h2 id="m4">四、钥节填空</h2><div class="fc-tools"><button id="czre" class="btn">🔄 换一组</button></div><div class="cloze" id="cloze"></div><p class="note">随机挖去钥节中的一个词，点按“显示”核对。</p>')
    b.append('<h2 id="m5">五、自测小考</h2><div class="quiz glass" id="quiz"><div class="qz-h"><span id="qzn">第 1 题</span><span id="qzs">得分 0</span></div><p class="qz-q" id="qzq"></p><div class="qz-o" id="qzo"></div><p class="qz-f" id="qzf" aria-live="polite"></p><div class="qz-b"><button class="btn" id="qznext">下一题 ➜</button><button class="btn ghost" id="qzre">重新开始</button></div></div>')
    b.append('<h2 id="m6">六、记忆宫殿：在你家里走一遍耶稣的一生</h2><div class="palace">'+"".join(f'<div class="pl glass reveal"><span>{a}</span><b>{c}</b><i>{d}</i><p>{e}</p></div>' for a,c,d,e in PAL)+'</div>')
    plan=[]; day=1
    for e,per in ((eps[1],[(1,3),(4,6),(7,9),(10,12),(13,14),(15,16)]),(eps[0],[(1,4),(5,7),(8,10),(11,13),(14,16),(17,19),(20,22),(23,25),(26,28)]),(eps[2],[(1,2),(3,5),(6,8),(9,11),(12,14),(15,17),(18,20),(21,22),(23,24)]),(eps[3],[(1,3),(4,6),(7,9),(10,12),(13,17),(18,21)])):
        for a,c in per: plan.append((day,f'{e["ab"]}{a}–{c}')); day+=1
    plan.append((day,"复习：口诀 + 小考 + 三大信经背诵"))
    b.append(f'<h2 id="m7">七、{len(plan)} 天通读四福音计划</h2><p class="note">建议先读最短、最早的马可福音，再读马太、路加，最后读约翰福音。</p><div class="plan" id="plan">'+"".join(f'<label class="pd glass"><input type="checkbox" data-d="{d}"><b>第 {d} 天</b><span>{t}</span></label>' for d,t in plan)+'</div><p class="note">勾选会保存在本机浏览器（localStorage）。</p>')
    data=dict(cz=[dict(t=vtext(r),r=r,w=WORDS) for r in CZ],q=Q(eps))
    b.append(f'<script id="qdata" type="application/json">{json.dumps(data,ensure_ascii=False).replace("</","<\\/")}</script>')
    return "".join(b)
